-- UUIDv5 namespace: c4283e2a-b750-48c6-a890-71cede7c2d0b (same namespace as
-- 20260726200000_training_v2_system_exercise_catalog.sql).
-- Key scheme (name input for uuid.v5, all flat strings under the shared namespace):
--   system exercise:        <system_key>                                      (unchanged convention)
--   template:                template:<presetId>
--   template revision:       template_revision:<presetId>:1
--   template unit:            template_unit:<presetId>:<dayIndex>
--   unit logical key:         template_unit_logical:<presetId>:<dayIndex>
--   template exercise:        template_exercise:<presetId>:<dayIndex>:<exerciseIndex>
--   exercise logical key:     template_exercise_logical:<presetId>:<dayIndex>:<exerciseIndex>
--   target set:               template_target_set:<presetId>:<dayIndex>:<exerciseIndex>:<setIndex>
--   set logical key:          template_target_set_logical:<presetId>:<dayIndex>:<exerciseIndex>:<setIndex>
-- presetId/dayIndex/exerciseIndex/setIndex all come from the legacy PRESET_PLANS array order in
-- apps/mobile/features/tools/training/utils/trainingUtils.js (0-based, in declaration order).

-- Part 1: 20 new canonical system exercises. Every legacy exercise name that has no exact
-- existing V2 system-exercise name match gets its own row, named exactly as the legacy
-- preset shows it. equipment is '{}' wherever the legacy name does not itself determine one
-- specific device/variant (never guessed) — see the accompanying report for the per-exercise
-- reasoning. On conflict: immutable seed content, never overwritten by a later migration run.
insert into public.training_exercises_v2 (
